/* ---------- SVG बनाने के छोटे हेल्पर (केवल इस फ़ाइल के डायग्राम के लिए) ---------- */
var MBGF = 'Noto Sans Devanagari, sans-serif';
function MBGfig(svg, cap) {
  /* सेक्शन रेंडरर ख़ुद <figure class="diagram"> लगाता है — यहाँ सिर्फ़ SVG + caption दीजिए */
  return svg + (cap ? '<figcaption>' + cap + '</figcaption>' : '');
}
function MBGdefs(id, color) {
  return '<defs><marker id="' + id + '" markerWidth="10" markerHeight="8" refX="9" refY="4" orient="auto">' +
    '<path d="M0,0 L10,4 L0,8 z" fill="' + (color || '#38bdf8') + '"/></marker></defs>';
}
function MBGbox(x, y, w, h, t1, t2, fill, stroke, fs) {
  return '<g><rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="12" fill="' + fill + '" stroke="' + stroke + '" stroke-width="2"/>' +
    '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + (t2 ? -3 : 6)) + '" text-anchor="middle" fill="#e8eefc" font-size="' + (fs || 15) + '" font-weight="700" font-family="' + MBGF + '">' + t1 + '</text>' +
    (t2 ? '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 17) + '" text-anchor="middle" fill="#9fb6d6" font-size="11.5" font-family="' + MBGF + '">' + t2 + '</text>' : '') +
    '</g>';
}
function MBGsmall(x, y, w, h, t, fill, stroke, fs) {
  return '<g><rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="8" fill="' + fill + '" stroke="' + stroke + '" stroke-width="1.6"/>' +
    '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 4) + '" text-anchor="middle" fill="#cfe3ff" font-size="' + (fs || 11.5) + '" font-weight="600" font-family="' + MBGF + '">' + t + '</text></g>';
}
function MBGline(x1, y1, x2, y2, label, color, arrow, mid, dash) {
  return '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="' + (color || '#38bdf8') + '" stroke-width="2.2"' +
    (arrow ? ' marker-end="url(#' + arrow + ')"' : '') + (dash ? ' stroke-dasharray="6 5"' : '') + '/>' +
    (label ? '<text x="' + ((mid != null) ? mid : (x1 + x2) / 2) + '" y="' + ((y1 + y2) / 2 - 7) + '" text-anchor="middle" fill="' + (color || '#7dd3fc') + '" font-size="11.5" font-family="' + MBGF + '">' + label + '</text>' : '');
}
function MBGtxt(x, y, t, color, fs, anchor, weight) {
  return '<text x="' + x + '" y="' + y + '" text-anchor="' + (anchor || 'middle') + '" fill="' + (color || '#9fb6d6') + '" font-size="' + (fs || 12.5) + '" font-weight="' + (weight || 600) + '" font-family="' + MBGF + '">' + t + '</text>';
}

/* ---------- डायग्राम 4.1 : सॉकेट के प्रकार (नाम: MBsockets) ---------- */
/* window.MBdiagSockets -> app.js का alias "MBsockets" */
window.MBdiagSockets = function MBdiagSockets() {
  var s = '<svg viewBox="0 0 900 400" xmlns="http://www.w3.org/2000/svg">' + MBGdefs('mbg3');
  s += MBGtxt(450, 24, 'LGA · PGA · BGA — तीनों में पिन कहाँ रहते हैं?', '#94a3c4', 13.5);
  /* LGA */
  s += '<rect x="30" y="48" width="260" height="270" rx="14" fill="#0f1626" stroke="#3b82f6" stroke-width="2"/>';
  s += MBGtxt(160, 74, 'LGA (Land Grid Array)', '#e8eefc', 13.5);
  s += '<rect x="60" y="210" width="200" height="26" rx="5" fill="#123a2b" stroke="#22c55e" stroke-width="2"/>';
  s += MBGtxt(160, 228, 'मदरबोर्ड (सॉकेट)', '#7dd3a8', 10.5);
  for (var i1 = 0; i1 < 11; i1++) s += '<line x1="' + (72 + i1 * 17) + '" y1="210" x2="' + (72 + i1 * 17) + '" y2="196" stroke="#d9a441" stroke-width="2"/>';
  s += MBGtxt(160, 186, 'स्प्रिंग पिन सॉकेट में', '#d9a441', 10.5);
  s += '<rect x="70" y="130" width="180" height="30" rx="5" fill="#1c232e" stroke="#8b98ad" stroke-width="2"/>';
  s += MBGtxt(160, 150, 'CPU — नीचे समतल पैड', '#c9d3e2', 10.5);
  for (var i2 = 0; i2 < 11; i2++) s += '<rect x="' + (78 + i2 * 16) + '" y="160" width="10" height="4" fill="#d9a441"/>';
  s += MBGtxt(160, 300, 'उदाहरण: LGA1700 · LGA1851 · AM5', '#8fb4dd', 11);
  /* PGA */
  s += '<rect x="320" y="48" width="260" height="270" rx="14" fill="#0f1626" stroke="#f59e0b" stroke-width="2"/>';
  s += MBGtxt(450, 74, 'PGA (Pin Grid Array)', '#e8eefc', 13.5);
  s += '<rect x="350" y="210" width="200" height="26" rx="5" fill="#123a2b" stroke="#22c55e" stroke-width="2"/>';
  s += MBGtxt(450, 228, 'सॉकेट में छेद (ZIF)', '#7dd3a8', 10.5);
  for (var i3 = 0; i3 < 11; i3++) s += '<ellipse cx="' + (362 + i3 * 17) + '" cy="204" rx="4" ry="5" fill="#0a0d14" stroke="#d9a441"/>';
  s += '<rect x="360" y="130" width="180" height="30" rx="5" fill="#1c232e" stroke="#8b98ad" stroke-width="2"/>';
  s += MBGtxt(450, 150, 'CPU — नीचे पिन', '#c9d3e2', 10.5);
  for (var i4 = 0; i4 < 11; i4++) s += '<line x1="' + (368 + i4 * 16) + '" y1="160" x2="' + (368 + i4 * 16) + '" y2="184" stroke="#d9a441" stroke-width="2.4"/>';
  s += MBGtxt(450, 300, 'उदाहरण: AM4 · AM3+ · FM2+ · Intel 478', '#8fb4dd', 11);
  /* BGA */
  s += '<rect x="610" y="48" width="260" height="270" rx="14" fill="#0f1626" stroke="#a78bfa" stroke-width="2"/>';
  s += MBGtxt(740, 74, 'BGA (Ball Grid Array)', '#e8eefc', 13.5);
  s += '<rect x="640" y="210" width="200" height="26" rx="5" fill="#123a2b" stroke="#22c55e" stroke-width="2"/>';
  s += MBGtxt(740, 228, 'मदरबोर्ड', '#7dd3a8', 10.5);
  s += '<rect x="650" y="166" width="180" height="34" rx="5" fill="#1c232e" stroke="#8b98ad" stroke-width="2"/>';
  s += MBGtxt(740, 188, 'चिप सीधे सोल्डर', '#c9d3e2', 10.5);
  for (var i5 = 0; i5 < 11; i5++) s += '<circle cx="' + (660 + i5 * 16) + '" cy="205" r="4.5" fill="#a78bfa"/>';
  s += MBGtxt(740, 300, 'CPU नहीं बदल सकते — सीधे बोर्ड पर', '#8fb4dd', 11);
  s += MBGtxt(450, 350, 'ZIF = Zero Insertion Force — लीवर खोलकर CPU रखें, फिर लीवर बंद करें। LGA में पिन मुड़े तो बोर्ड ख़राब; PGA में पिन मुड़े तो CPU ख़राब।', '#94a3c4', 11.5);
  s += MBGtxt(450, 376, 'लैपटॉप में लगभग हमेशा BGA — इसलिए लैपटॉप का CPU अपग्रेड नहीं होता।', '#f59e0b', 11.5);
  s += '</svg>';
  return MBGfig(s, 'तीन सॉकेट प्रकार — पिन किस तरफ़ हैं, यही तय करता है कि ख़राबी पर बोर्ड बदलना है या CPU.');
};

/* ---------- डायग्राम 5.2 : ग्राफ़िक्स का रास्ता (नाम: MBgraphics) ---------- */
/* window.MBdiagGraphics -> app.js का alias "MBgraphics" */
window.MBdiagGraphics = function MBdiagGraphics() {
  var s = '<svg viewBox="0 0 900 460" xmlns="http://www.w3.org/2000/svg">' + MBGdefs('mbg5');
  s += MBGtxt(450, 24, 'डिस्प्ले का रास्ता — iGPU बनाम dGPU', '#94a3c4', 13.5);
  /* iGPU */
  s += '<rect x="30" y="50" width="400" height="350" rx="16" fill="#0f1b2e" stroke="#3b82f6" stroke-width="2"/>';
  s += MBGtxt(230, 78, 'रास्ता A — इंटीग्रेटेड GPU (iGPU)', '#7dd3fc', 13.5);
  s += MBGbox(60, 98, 150, 76, 'CPU के अंदर iGPU', 'Intel UHD/Iris Xe · AMD Radeon', '#172a1f', '#22c55e');
  s += MBGline(215, 136, 255, 136, 'चित्र डेटा', '#22c55e', 'mbg5');
  s += MBGbox(258, 98, 140, 76, 'मदरबोर्ड', 'चिपसेट से नहीं — सीधे CPU से', '#1b2a44', '#22d3ee');
  s += MBGline(330, 178, 330, 220, 'HDMI / DP / VGA', '#22d3ee', 'mbg5');
  s += MBGbox(250, 224, 160, 70, 'बोर्ड का डिस्प्ले पोर्ट', 'I/O पैनल पर', '#152238', '#38bdf8');
  s += MBGline(330, 298, 330, 336, 'डिस्प्ले केबल', '#38bdf8', 'mbg5');
  s += MBGbox(240, 340, 180, 50, 'मॉनिटर', '', '#1c232e', '#8b98ad');
  s += MBGtxt(230, 260, 'शर्त: बोर्ड में पोर्ट हो + CPU में iGPU हो', '#f59e0b', 11, 'middle');
  /* dGPU */
  s += '<rect x="470" y="50" width="400" height="350" rx="16" fill="#221430" stroke="#a78bfa" stroke-width="2"/>';
  s += MBGtxt(670, 78, 'रास्ता B — डिस्क्रीट GPU कार्ड', '#d8c4ff', 13.5);
  s += MBGbox(500, 98, 150, 76, 'CPU', 'iGPU का इस्तेमाल नहीं', '#172a1f', '#22c55e');
  s += MBGline(655, 136, 700, 136, 'PCIe ×16', '#a78bfa', 'mbg5');
  s += MBGbox(703, 98, 140, 76, 'PCIe x16 स्लॉट', 'सीधे CPU से जुड़ा', '#2a1c31', '#a78bfa');
  s += MBGline(773, 178, 773, 220, '75W स्लॉट से', '#a78bfa', 'mbg5');
  s += MBGbox(693, 224, 160, 70, 'ग्राफ़िक्स कार्ड', '+ 6/8-pin पावर केबल', '#2a1c31', '#c084fc');
  s += MBGline(773, 298, 773, 336, 'HDMI / DP', '#c084fc', 'mbg5');
  s += MBGbox(683, 340, 180, 50, 'मॉनिटर (GPU के पोर्ट में)', '#1c232e', '#8b98ad', 11.5);
  s += MBGtxt(670, 260, 'शर्त: केस में जगह + SMPS में पावर', '#f59e0b', 11);
  s += MBGtxt(450, 430, 'सबसे आम ग़लती: कार्ड लगा है पर केबल मदरबोर्ड के HDMI में — स्क्रीन काली। केबल हमेशा उसी पोर्ट में जो असल में चित्र दे रहा है।', '#f59e0b', 12);
  s += '</svg>';
  return MBGfig(s, 'iGPU का चित्र मदरबोर्ड के पोर्ट से और dGPU का अपने कार्ड के पोर्ट से निकलता है — दोनों का रास्ता अलग।');
};

