        ['Ryzen 5 5600G (APU)', 'AM4', 'A520 / B450 / B550', 'DDR4', 'iGPU मिलेगा — ग्राफ़िक्स कार्ड की ज़रूरत नहीं'],
        ['Ryzen 7 5800X3D', 'AM4', 'B550 / X570 (मज़बूत VRM)', 'DDR4', 'OC नहीं होता, पर गर्म — अच्छा कूलर'],
        ['Ryzen 5 7600 / 7 7700', 'AM5', 'B650', 'DDR5 only', 'स्टॉक कूलर के साथ आते हैं (कुछ में)'],
        ['Ryzen 7 7800X3D / 9 7950X', 'AM5', 'B650E / X670E (मज़बूत VRM)', 'DDR5', 'मज़बूत VRM + टॉवर कूलर/AIO'],
        ['Ryzen 9 9950X', 'AM5', 'X870E / B650E (14+ फ़ेज़)', 'DDR5', 'सस्ते बोर्ड पर 170W CPU न लें'],
        ['Threadripper 7960X', 'sTR5', 'TRX50 / WR90', 'DDR5 ECC आदि', '₹1 लाख+ — सिर्फ़ वर्कस्टेशन'],
        ['Xeon E-2300', 'LGA1200', 'C256 (सर्वर बोर्ड)', 'DDR4 ECC', 'सामान्य बोर्ड में नहीं चलेगा'],
        ['Xeon Silver/Gold', 'LGA4677', 'C741 / W790', 'DDR5 RDIMM', 'सर्वर प्लेटफ़ॉर्म; सामान्य बोर्ड नहीं']
